mod audio;
mod console;
mod diag;
// BIO program for the I2S mic, vendored verbatim from bio-sim. Autogenerated -- do not edit.
mod i2s_bio;
#[cfg(feature = "mel")]
mod mel;
mod pins;
mod uart_out;

use audio::{AudioSource, I2sAudio};
use diag::Diag;
use uart_out::UartOut;
// Without `mel`, main builds a level-only frame directly (the mel module isn't compiled).
#[cfg(not(feature = "mel"))]
use triangel_shared::mel::MelFrame;

fn main() -> ! {
    // A panic anywhere prints over USB serial before the process dies; the USB
    // server owns the message once sent, so it still reaches the host. Without
    // this, a failed BIO resource claim in I2sAudio::new() is invisible.
    std::panic::set_hook(Box::new(|info| {
        Diag::new().line(&format!("PANIC: {}", info));
    }));

    // USB and the heartbeat come up before anything that can block, so a stalled
    // startup still reports the stage it stopped at.
    let d = Diag::new();
    diag::spawn_heartbeat();
    d.line("");
    d.line("=== ear ===");
    diag::stage(&d, 0);

    log_server::init_wait().unwrap();
    log::set_max_level(log::LevelFilter::Info);
    log::info!("ear starting, PID {}", xous::process::id());

    let hal = bao1x_hal_service::Hal::new();
    hal.set_preemption(true);
    diag::stage(&d, 1);

    let tt = ticktimer::Ticktimer::new().unwrap();

    d.line("I2S pins: PB1 = BCLK, PB2 = SD, PB3 = WS");
    diag::stage(&d, 2);
    let mut mic = I2sAudio::new();
    diag::stage(&d, 3);

    let mut uart_out = UartOut::new();

    d.line(&format!("FIFO0 level {}", mic.fifo_level()));
    console::help(&d);
    console::spawn();
    diag::stage(&d, 4);

    log::info!("ear ready");

    // With the `mel` feature: run the 24-band mel filterbank on each frame and
    // send framed MelFrames to the eye. Otherwise: the temporary level path - a simple
    // RMS from each frame sent as one 0-255 byte.
    #[cfg(feature = "mel")]
    let mut processor = mel::MelProcessor::new();

    loop {
        // The mic is not Send, so diagnostic commands run here rather than on the
        // console thread. Returns immediately when no key has been pressed.
        console::service(&d, &tt, &mut mic);

        let frame = mic.read_frame();
        #[cfg(feature = "mel")]
        uart_out.send(&processor.process(&frame));
        #[cfg(not(feature = "mel"))]
        {
            // Level-only frame from a simple RMS - same 53-byte wire format as the mel
            // path, just with the bands zeroed. 1.8 = sensitivity; higher = more.
            let rms = (frame.iter().map(|&s| (s as f32 / 32768.0).powi(2)).sum::<f32>()
                / frame.len() as f32).sqrt();
            let level = ((rms * 1.8).clamp(0.0, 1.0) * 65535.0) as u16;
            uart_out.send(&MelFrame::level_only(level, rms > 0.02));
        }
    }
}
